import { randomBytes } from 'node:crypto';
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { paths } from './paths.ts';

export interface Config {
	/** better-auth secret, generated by `nolune init`. */
	authSecret: string;
	anthropicApiKey?: string;
	/** For `nolune generate image` with the openai image provider. */
	openaiApiKey?: string;
	openrouterApiKey?: string;
	/** For chats on xAI's Grok models (xai.ts). */
	xaiApiKey?: string;
	/**
	 * Custom providers (custom-providers.ts): the family's own model servers, like Ollama or LM
	 * Studio, each with an id from its name, the API it speaks, an address, and a key when it
	 * wants one.
	 */
	customProviders?: {
		id: string;
		name: string;
		api: 'openai' | 'anthropic';
		url: string;
		key?: string;
	}[];
	/**
	 * The Claude Code executable that chats on the Claude plan run (claude-plan.ts). Found on the
	 * PATH and in the usual install folders when not set.
	 */
	claudePath?: string;
	/**
	 * What `nolune generate image` uses, as `<provider>/<model>`. Unset: gpt-image-2.5-flare on
	 * the first of an OpenAI key, an OpenRouter key and the nolune plan that nolune has.
	 */
	imageModel?: string;
	/**
	 * Where memory search gets embeddings, to find facts by meaning (memory-embeddings.ts): off, or
	 * a provider's model with its key, or a custom provider's that speaks OpenAI's API
	 * (`custom-openai`, the model `<id>/<model>`) like Ollama, LM Studio or oMLX, or the nolune plan's.
	 * Unset: OpenAI's key, else OpenRouter's, else the nolune plan.
	 */
	embeddings?:
		'off' | { provider: 'openai' | 'openrouter' | 'nolune-plan' | 'custom-openai'; model: string };
	/** Extra environment variables for commands the agent runs (e.g. FIRECRAWL_API_KEY). */
	commandEnv?: Record<string, string>;
	/**
	 * How the agent's commands run (command-safety.ts): `auto`, a model checks each one first and
	 * blocks what could do harm nobody asked for; `unrestricted`, they run as they are. Unset: auto.
	 */
	commandMode?: 'auto' | 'unrestricted';
	/** The preset whose model does auto mode's checks. Unset, or removed: each chat's own model. */
	safetyPresetId?: string;
	/** Where `nolune start` listens. Defaults: 127.0.0.1:5780 (put a tunnel or proxy in front). */
	host?: string;
	port?: number;
	/** Public URL people open, e.g. https://nolune.example.com. Defaults to http://localhost:<port>. */
	origin?: string;
	/**
	 * The relay (packages/relay) that gives nolune its public address, set by `nolune relay enable`:
	 * where it runs, the name and address it gave, and the token the gateway connects with. While
	 * it's set, its address is the origin.
	 */
	relay?: RelayConfig;
}

export interface RelayConfig {
	server: string;
	name: string;
	url: string;
	token: string;
}

export const DEFAULT_PORT = 5780;

/** nolune's own relay, for everyone who doesn't run one (`nolune relay enable --server`). */
export const DEFAULT_RELAY_SERVER = 'https://relay.nolune.dev';

/** The address people open: the relay's while it's on, else the origin set, else this computer. */
export function publicOrigin(config: Config): string {
	return config.relay?.url ?? config.origin ?? `http://localhost:${config.port ?? DEFAULT_PORT}`;
}

/** Where each provider's API key is kept, and the environment variable used when it isn't. */
export const API_KEYS = {
	anthropic: { label: 'Anthropic', field: 'anthropicApiKey', env: 'ANTHROPIC_API_KEY' },
	openai: { label: 'OpenAI', field: 'openaiApiKey', env: 'OPENAI_API_KEY' },
	openrouter: { label: 'OpenRouter', field: 'openrouterApiKey', env: 'OPENROUTER_API_KEY' },
	xai: { label: 'xAI', field: 'xaiApiKey', env: 'XAI_API_KEY' }
} as const satisfies Record<string, { label: string; field: keyof Config; env: string }>;

export type ApiKeyProvider = keyof typeof API_KEYS;

export function isApiKeyProvider(value: string): value is ApiKeyProvider {
	return Object.hasOwn(API_KEYS, value);
}

/** The key in use: config.json's, else the environment's. Read on every call, so changes apply at once. */
export function configuredApiKey(
	provider: ApiKeyProvider
): { key: string; source: 'config' | 'env' } | null {
	const { field, env } = API_KEYS[provider];
	let saved: string | undefined;
	try {
		saved = readConfig()[field];
	} catch {
		// not set up yet: only the environment can have one
	}
	if (saved) return { key: saved, source: 'config' };
	const fromEnv = process.env[env];
	return fromEnv ? { key: fromEnv, source: 'env' } : null;
}

/** How a missing or rejected key gets fixed, for messages people and the agent see. */
export function apiKeyHelp(provider: ApiKeyProvider): string {
	return `An admin can add one under Models & keys in nolune, or with \`nolune key set ${provider}\`.`;
}

export function configExists(): boolean {
	return existsSync(paths.config);
}

export function readConfig(): Config {
	if (!configExists()) {
		throw new Error(`No config at ${paths.config}. Run \`nolune init\` first.`);
	}
	return JSON.parse(readFileSync(paths.config, 'utf8')) as Config;
}

export function writeConfig(config: Config): void {
	mkdirSync(paths.home, { recursive: true });
	writeFileSync(paths.config, JSON.stringify(config, null, '\t') + '\n', { mode: 0o600 });
	chmodSync(paths.config, 0o600);
}

/** Creates config.json with a fresh auth secret if it doesn't exist yet. */
export function initConfig(): { created: boolean } {
	if (configExists()) return { created: false };
	writeConfig({ authSecret: randomBytes(32).toString('base64url') });
	return { created: true };
}

export function updateConfig(change: (config: Config) => void): Config {
	const config = readConfig();
	change(config);
	writeConfig(config);
	return config;
}
